#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/button_base/button_base.hpp"
#include "gui_forms/controls/button_base/check_box/check_box_values/check_box_values.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// CheckBox's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/check_box.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// Unchecked, checked or indeterminate (CheckState); a view onto the check state. Indeterminate becomes checked unless three_state. A change raises check_state_changed, then checked_changed when checked changes. Outside the enumeration throws std::invalid_argument.
template <typename Declaring>
struct CheckBoxCheckStateCapability {
    PropertyView<CheckState, CheckBoxCheckStateCapability<Declaring>> check_state;

    static void assign(CheckBoxCheckStateCapability& capability, CheckState incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.check_state), std::move(incoming));
    }

    static CheckState read(const CheckBoxCheckStateCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        CheckState current = control.read_view(capability.check_state);
        return current;
    }
};

// Whether the box is checked (Checked); a view onto check_state: a write sets checked or unchecked.
template <typename Declaring>
struct CheckBoxCheckedCapability {
    PropertyView<bool, CheckBoxCheckedCapability<Declaring>> checked;

    static void assign(CheckBoxCheckedCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.checked), std::move(incoming));
    }

    static bool read(const CheckBoxCheckedCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        bool current = control.read_view(capability.checked);
        return current;
    }
};

// Whether the box also takes the indeterminate state (ThreeState); clearing it turns an indeterminate box checked.
template <typename Declaring>
struct CheckBoxThreeStateCapability {
    PropertyCell<bool, CheckBoxThreeStateCapability<Declaring>> three_state{false};

    static void assign(CheckBoxThreeStateCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.three_state), incoming);
        if (!capability.three_state.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.three_state));
    }
};

// Whether activation advances the check state (AutoCheck).
template <typename Declaring>
struct CheckBoxAutoCheckCapability {
    PropertyCell<bool, CheckBoxAutoCheckCapability<Declaring>> auto_check{true};

    static void assign(CheckBoxAutoCheckCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.auto_check), incoming);
        if (!capability.auto_check.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.auto_check));
    }
};

// Normal or button (Appearance): only the visual projection changes. Outside the enumeration throws std::invalid_argument.
template <typename Declaring>
struct CheckBoxAppearanceStyleCapability {
    PropertyCell<CheckBoxAppearance, CheckBoxAppearanceStyleCapability<Declaring>> appearance{CheckBoxAppearance::normal};

    static void assign(CheckBoxAppearanceStyleCapability& capability, CheckBoxAppearance incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.appearance), incoming);
        if (!capability.appearance.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.appearance));
    }
};

// How the check mark draws: classic, modern or toggle (std::invalid_argument outside them).
template <typename Declaring>
struct CheckBoxIndicatorStyleCapability {
    PropertyCell<ChoiceIndicatorStyle, CheckBoxIndicatorStyleCapability<Declaring>> indicator_style{ChoiceIndicatorStyle::classic};

    static void assign(CheckBoxIndicatorStyleCapability& capability, ChoiceIndicatorStyle incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.indicator_style), incoming);
        if (!capability.indicator_style.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.indicator_style));
    }
};

// CheckState as a property value; defined beside CheckBox's table.
template <>
struct PropertyValueTraits<CheckState> {
    static PropertyType type();
    static BindingValue to_binding(CheckState value);
    static CheckState from_binding(const BindingValue& value);
};

// ChoiceIndicatorStyle as a property value; defined beside CheckBox's table.
template <>
struct PropertyValueTraits<ChoiceIndicatorStyle> {
    static PropertyType type();
    static BindingValue to_binding(ChoiceIndicatorStyle value);
    static ChoiceIndicatorStyle from_binding(const BindingValue& value);
};

// Every CheckBox capability, in the order the declaring class takes them.
template <typename Declaring>
struct CheckBoxCapabilities : public CheckBoxCheckStateCapability<Declaring>,
                              public CheckBoxCheckedCapability<Declaring>,
                              public CheckBoxThreeStateCapability<Declaring>,
                              public CheckBoxAutoCheckCapability<Declaring>,
                              public CheckBoxAppearanceStyleCapability<Declaring>,
                              public CheckBoxIndicatorStyleCapability<Declaring> {};

} // namespace gui_forms
